package com.ias.identity.auth;

import com.ias.trust.*;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
import java.time.Instant;
import java.util.*;

/** Current facts only. This controller never grants access to a ticket object. */
@RestController
public class TicketAuthorizationController {
 final AuthService auth;final JdbcTemplate db;
 public TicketAuthorizationController(AuthService auth,JdbcTemplate db){this.auth=auth;this.db=db;}
 static long id(Object v){try{long n=Long.parseLong(v.toString());if(n<1)throw new Exception();return n;}catch(Exception e){throw new Problem(400,"VALIDATION_ERROR");}}
 Map<String,Object> caller(Map<String,Object>b,HttpServletRequest r){var a=auth.introspect((String)b.get("sessionToken"),"TICKET_READ",null,Chain.nanoDeadline(Chain.deadline(r)));if(!"EMPLOYEE".equals(a.get("identityType")))throw new Problem(403,"ACCESS_DENIED");return a;}
 Map<String,Object> facts(long tenant,long user){
  var rows=db.queryForList("SELECT u.status,u.must_change_password,u.security_version,u.row_version,u.display_name,u.department_id,d.code department_code,d.enabled department_enabled,t.status tenant_status,t.security_epoch FROM identity_user u JOIN tenant t ON t.id=u.tenant_id LEFT JOIN identity_employee_configuration c ON c.user_id=u.id AND c.tenant_id=u.tenant_id LEFT JOIN identity_department d ON d.id=u.department_id AND d.tenant_id=u.tenant_id WHERE u.id=? AND u.tenant_id=? AND u.identity_type='EMPLOYEE'",user,tenant);
  if(rows.isEmpty())throw new Problem(404,"TARGET_NOT_ACCESSIBLE");var row=rows.getFirst();
  var out=new LinkedHashMap<String,Object>();out.put("userId",Long.toString(user));out.put("tenantId",Long.toString(tenant));out.put("enabled",((Number)row.get("status")).intValue()==1&&((Number)row.get("must_change_password")).intValue()==0&&((Number)row.get("tenant_status")).intValue()==1);out.put("displayName",row.get("display_name"));out.put("securityVersion",row.get("security_version").toString());out.put("rowVersion",row.get("row_version").toString());out.put("securityEpoch",row.get("security_epoch").toString());out.put("departmentId",row.get("department_id")==null?null:row.get("department_id").toString());out.put("departmentCode",row.get("department_code"));out.put("departmentEnabled",row.get("department_enabled")!=null&&((Number)row.get("department_enabled")).intValue()==1);
  out.put("reopenReviewDepartmentIds",db.queryForList("SELECT department_id FROM identity_reopen_department_scope WHERE tenant_id=? AND user_id=? AND enabled=1 ORDER BY department_id",Long.class,tenant,user).stream().map(Object::toString).toList());out.put("reopenReviewDepartments",db.queryForList("SELECT d.id,d.name FROM identity_reopen_department_scope s JOIN identity_department d ON d.tenant_id=s.tenant_id AND d.id=s.department_id WHERE s.tenant_id=? AND s.user_id=? AND s.enabled=1 ORDER BY d.id",tenant,user).stream().map(d->Map.of("id",d.get("id").toString(),"name",d.get("name"))).toList());
  out.put("permissions",db.queryForList("SELECT capability_code FROM identity_user_capability WHERE user_id=? AND enabled=1 ORDER BY capability_code",String.class,user));
  out.put("companyIds",db.queryForList("SELECT company_id FROM identity_employee_company_scope WHERE tenant_id=? AND user_id=? AND enabled=1 ORDER BY company_id",Long.class,tenant,user).stream().map(Object::toString).toList());
  out.put("assignableDepartmentIds",db.queryForList("SELECT s.department_id FROM identity_employee_department_scope s JOIN identity_department d ON d.id=s.department_id AND d.tenant_id=s.tenant_id WHERE s.tenant_id=? AND s.user_id=? AND s.enabled=1 ORDER BY d.id",Long.class,tenant,user).stream().map(Object::toString).toList());out.put("assignableDepartments",db.queryForList("SELECT d.id,d.name FROM identity_employee_department_scope s JOIN identity_department d ON d.id=s.department_id AND d.tenant_id=s.tenant_id WHERE s.tenant_id=? AND s.user_id=? AND s.enabled=1 AND d.enabled=1 ORDER BY d.id",tenant,user).stream().map(d->Map.of("id",d.get("id").toString(),"name",d.get("name"))).toList());var latest=db.queryForMap("SELECT u.security_version,t.security_epoch FROM identity_user u JOIN tenant t ON t.id=u.tenant_id WHERE u.id=? AND u.tenant_id=?",user,tenant);if(!latest.get("security_version").toString().equals(out.get("securityVersion"))||!latest.get("security_epoch").toString().equals(out.get("securityEpoch")))throw new Problem(503,"DEPENDENCY_UNAVAILABLE");out.put("checkedAt",Instant.now().toString());return out;
 }
 public static boolean eligible(Map<String,Object> f,String department){return Boolean.TRUE.equals(f.get("enabled"))&&Boolean.TRUE.equals(f.get("departmentEnabled"))&&department.equals(f.get("departmentId"))&&((List<?>)f.get("permissions")).containsAll(List.of("ticket.engineer.read","ticket.assignment.accept","ticket.record"));}
 void assignScope(Map<String,Object>a,String department,Object purpose){if("REOPEN".equals(purpose)&&(!Boolean.TRUE.equals(a.get("enabled"))||!Boolean.TRUE.equals(a.get("departmentEnabled"))||!((List<?>)a.get("permissions")).contains("ticket.read")))throw new Problem(403,"ACCESS_DENIED");if(purpose!=null&&!Set.of("ASSIGN","TRANSFER","REOPEN").contains(purpose))throw new Problem(400,"VALIDATION_ERROR");if(!((List<?>)a.get("permissions")).contains("TRANSFER".equals(purpose)?"ticket.transfer.request":"REOPEN".equals(purpose)?"ticket.reopen.review":"ticket.assign")||!((List<?>)a.get("assignableDepartmentIds")).contains(department))throw new Problem(404,"TARGET_NOT_ACCESSIBLE");}
 @PostMapping("/internal/identity/ticket-authorizations") public Map<String,Object> authorization(@RequestBody Map<String,Object>b,HttpServletRequest r){
  if("TRANSFER_SYSTEM".equals(b.get("purpose"))){if(!"ticket-identity".equals(r.getAttribute("ias.chain.edge"))||!b.keySet().equals(Set.of("purpose","tenantId","targetUserId","departmentId")))throw new Problem(403,"ACCESS_DENIED");boolean qualified;try{qualified=eligible(facts(id(b.get("tenantId")),id(b.get("targetUserId"))),Long.toString(id(b.get("departmentId"))));}catch(Problem e){if(e.status!=404)throw e;qualified=false;}return Map.of("eligible",qualified,"checkedAt",Instant.now().toString());}var a=caller(b,r);long tenant=id(a.get("tenantId"));var f=facts(tenant,id(a.get("userId")));if(!Objects.equals(f.get("securityVersion"),a.get("securityVersion"))||!Objects.equals(f.get("securityEpoch"),a.get("securityEpoch")))throw new Problem(401,"SESSION_INVALID");
  if(b.get("targetUserId")!=null){String department=Long.toString(id(b.get("departmentId")));assignScope(f,department,b.get("purpose"));long target=id(b.get("targetUserId"));var rows=db.queryForList("SELECT id FROM identity_user WHERE id=? AND tenant_id=? AND identity_type='EMPLOYEE'",target,tenant);boolean qualified=!rows.isEmpty()&&eligible(facts(tenant,target),department);return Map.of("userId",Long.toString(target),"eligible",qualified,"checkedAt",Instant.now().toString());}
  return f;
 }
 @PostMapping("/internal/identity/ticket-candidates") public Map<String,Object> candidates(@RequestBody Map<String,Object>b,HttpServletRequest r){
  var a=caller(b,r);long tenant=id(a.get("tenantId"));var f=facts(tenant,id(a.get("userId")));if(!Objects.equals(f.get("securityVersion"),a.get("securityVersion"))||!Objects.equals(f.get("securityEpoch"),a.get("securityEpoch")))throw new Problem(401,"SESSION_INVALID");String department=Long.toString(id(b.get("departmentId")));assignScope(f,department,b.get("purpose"));
  long page=b.get("page")==null?1:id(b.get("page")),size=b.get("size")==null?20:id(b.get("size"));if(page>1000000||!Set.of(20L,50L,100L).contains(size))throw new Problem(400,"VALIDATION_ERROR");String keyword=b.get("keyword")==null?"":b.get("keyword").toString();if(keyword.length()>100)throw new Problem(400,"VALIDATION_ERROR");
  String where=" FROM identity_user u JOIN identity_employee_configuration c ON c.user_id=u.id AND c.tenant_id=u.tenant_id JOIN identity_department d ON d.id=u.department_id AND d.tenant_id=u.tenant_id WHERE u.tenant_id=? AND u.identity_type='EMPLOYEE' AND u.status=1 AND u.must_change_password=0 AND d.id=? AND d.enabled=1 AND (? IS NULL OR u.id<>?) AND u.display_name LIKE ? ESCAPE '!' AND (SELECT COUNT(*) FROM identity_user_capability p WHERE p.user_id=u.id AND p.enabled=1 AND p.capability_code IN ('ticket.engineer.read','ticket.assignment.accept','ticket.record'))=3";
  String q="%"+keyword.replace("!","!!").replace("%","!%").replace("_","!_")+"%";long total=db.queryForObject("SELECT COUNT(*)"+where,Long.class,tenant,id(department),b.get("excludeUserId"),b.get("excludeUserId"),q);
  var items=db.queryForList("SELECT u.id,u.display_name,u.department_id"+where+" ORDER BY u.id LIMIT ? OFFSET ?",tenant,id(department),b.get("excludeUserId"),b.get("excludeUserId"),q,size,(page-1)*size).stream().map(row->Map.of("userId",row.get("id").toString(),"displayName",row.get("display_name"),"departmentId",department)).toList();
  return Map.of("items",items,"total",total,"page",page,"size",size,"departmentId",department,"checkedAt",Instant.now().toString());
 }
}

